 f.admit(a);f.admit(b);
 const auto send=[&](Client& client,GroupCommand& command,unsigned now){command.operationId=++client.operation;command.runtime=client.own.runtime;command.loadRevision=client.own.loadRevision;CHECK(f.state.receive(client.connection,f.commandFrame(client,command),at(now))==RuntimeStatus::ready);Frame frame;const bool available=f.state.takeReply(client.connection,frame);CHECK(available);GroupReply result;if(available){CHECK(frame.kind==MessageKind::spectrumReply&&frame.session==client.session);CHECK(decodeGroupReply(bytes(frame.payload),result));CHECK(result.operationId==command.operationId);f.state.finishReply(client.connection,true);}return result;};
