 CHECK(send(b,publish,100).status==GroupReplyStatus::ready);
 auto readStorage=std::make_unique<GroupCommand>();auto& read=*readStorage;read.action=GroupAction::spectrumRead;read.spectrumPeers={b.own.project.group->member};const auto received=send(a,read,100);CHECK(received.status==GroupReplyStatus::ready&&received.spectra.size()==1);if(!received.spectra.empty())CHECK(received.spectra.front()==value);
 CHECK(send(b,publish,200).status!=GroupReplyStatus::ready);CHECK(f.state.alive(a.connection)&&f.state.alive(b.connection));
 CHECK(send(a,read,2101).spectra.empty());
 ++value.sequence;CHECK(send(b,publish,2200).status==GroupReplyStatus::ready);
 auto withdrawStorage=std::make_unique<GroupCommand>();auto& withdraw=*withdrawStorage;withdraw.action=GroupAction::spectrumWithdraw;CHECK(send(b,withdraw,2300).status==GroupReplyStatus::ready);CHECK(send(a,read,2300).spectra.empty());
 auto& legacy=f.add(72);f.admit(legacy);auto deniedStorage=std::make_unique<GroupCommand>();auto& denied=*deniedStorage;denied.operationId=++legacy.operation;denied.runtime=legacy.own.runtime;denied.loadRevision=1;denied.action=GroupAction::spectrumRead;denied.spectrumPeers=read.spectrumPeers;CHECK(f.state.receive(legacy.connection,f.commandFrame(legacy,denied),at(2400))==RuntimeStatus::invalidMessage);CHECK(!f.state.alive(legacy.connection));CHECK(f.state.alive(a.connection)&&f.state.alive(b.connection));
